def tope_del_pasillo(capacidades):
    """Devuelve la capacidad MAS GRANDE de la fila, no la mas pequena.

    POR QUE EL MAXIMO: el reparto de mas abajo ya manda el trabajo al cerebro que SI
    aguanta el tamano, asi que recortar antes a la medida del mas chico tira material
    para nada. Cortar por el minimo deja al revisor sin el trozo que si iba pegado.

    - lista vacia -> 0 (no recortar nada)
    - si no es lista, o trae cosas que no son numeros, se salta lo que no sirva;
      si no queda nada, devuelve 0.
    """
    if not isinstance(capacidades, (list, tuple)):
        return 0
    validas = [c for c in capacidades if isinstance(c, (int, float)) and not isinstance(c, bool)]
    if not validas:
        return 0
    return max(validas)
